           viewBox="0 0 26 26"
           fill="none"
           stroke="currentColor"
           stroke-width="1.5"
           stroke-linecap="round"
           stroke-linejoin="round">
        <polyline points="3 6 5 6 21 6"></polyline>
        <path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 
                 1-2-2V6m3 0V4a2 2 0 0 
                 1 2-2h4a2 2 0 0 1 2 2v2"></path>
      </svg>

      <svg v-else
           xmlns="http://www.w3.org/2000/svg" 
           width="26" height="26" 
           fill="currentColor" 
           class="bi bi-check2-circle" 
           viewBox="0 0 16 16">
        <path d="M2.5 8a5.5 5.5 0 0 1 
                 8.25-4.764.5.5 
                 0 0 0 .5-.866A6.5 6.5 
