                                        fill="none"
                                        stroke="currentColor"
                                        stroke-width="1.5"
                                        stroke-linecap="round"
                                        stroke-linejoin="round"
                                        class="text-info"
                                        data-bs-toggle="modal" data-bs-target="#requisitionItems"
                                        
                                    >
                                        <path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"></path>
                                        <circle cx="12" cy="12" r="3"></circle>
                                    </svg>
                                </a>

                                <router-link 
                                v-if="props.row.status.key === 'Issued' || props.row.status.key === 'Partial Issued'"
                                :to="`/good-issue-notes/${props.row.id}`">
                                <svg xmlns="http://www.w3.org/2000/svg" width="26" height="26" fill="currentColor" class="bi bi-arrow-bar-right" viewBox="0 0 16 16">
  <path fill-rule="evenodd" d="M6 8a.5.5 0 0 0 .5.5h5.793l-2.147 2.146a.5.5 0 0 0 .708.708l3-3a.5.5 0 0 0 0-.708l-3-3a.5.5 0 0 0-.708.708L12.293 7.5H6.5A.5.5 0 0 0 6 8m-2.5 7a.5.5 0 0 1-.5-.5v-13a.5.5 0 0 1 1 0v13a.5.5 0 0 1-.5.5"/>
</svg>
                                </router-link>

                
                            </template>
                           
                        </v-client-table>
                    </div>
                </div>
            </div>
        </div>
            <!-- requisition table ends -->

            <!-- requisition items sterts -->
<div class="modal fade mymodal" id="requisitionItems" data-bs-backdrop="false" data-bs-keyboard="false" tabindex="-1" aria-labelledby="staticBackdropLabel" aria-hidden="true">
  <div class="modal-dialog modal-fullscreen">
    <div class="modal-content">
      <!-- Header -->
      <div class="modal-header">
        <h1 class="modal-title fs-5" id="staticBackdropLabel">Requisition Items</h1>
        <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close" @click="clearForm()" id="close-issue-modal"></button>
      </div>

      <!-- Body -->
      <div class="modal-body">
                     <div class="col-xl-12 col-lg-12 col-sm-12 layout-spacing">
                <div class="panel p-0">
                    <div class="custom-table table3 ">
<table class="table table-bordered table-striped">
      <thead >
        <tr>
          <th>Requester</th>
          <th>Date Requested</th>
          <th>Source</th>
          <th>Purpose</th>
          <th>Project</th>
          <th>Status</th>
        </tr>
      </thead>
      <tbody>
        <tr >
          <td>{{ requisition.requester }}</td>
          <td>{{ requisition.date }}</td>
           <td>{{ requisition.type }}</td>
          <td>{{ requisition.purpose }}</td>
          <td>{{ requisition.project }}</td>
          <td> <span class="mb-0 badge" :class="`badge-${requisition.status?.class}`">
                  {{ requisition.status?.key }}
                </span></td>
        </tr>
     <tr v-if="requisition.description">
      <td colspan="5"><b> Brief Description : </b> {{ requisition.description }}</td>
    </tr>
      <tr v-if="requisition.remark">
      <td colspan="5"> <b> Remark :  </b> {{ requisition.remark }}</td>
    </tr>
      </tbody>
    </table>

    </div>
    </div>
    </div>

                <!-- approval button starts -->
                     <div class="mb-2 text-center fw-bold" style="font-size: x-large;">
      <strong>Total Cost: </strong>
      <span>
        {{
          requisition?.items?.reduce((sum, item) => {
            const qty = Number(item.quantity) || 0;
            const rate = Number(item.rate) || 0;
            return sum + qty * rate;
          }, 0).toLocaleString() + '/='
        }}
      </span>
    </div>
  <div v-if="(requisition.status?.key === 'Unapproved' || requisition.status?.key === 'Remarked' || requisition.status?.key === 'Rejected' ) && user_permissions.includes('is_md')" class="mb-2 text-center">
  <div class="btn-group mb-3">
    <button v-if="user_permissions.includes('is_programmer')" class="btn btn-secondary me-2" @click="status = 2" :disabled="spinner">Unapprove</button>
    <button class="btn btn-primary me-2" @click="status = 3" :disabled="spinner">Approve</button>
    <button class="btn btn-danger me-2" @click="status = 4" :disabled="spinner">Reject</button>
    <button class="btn btn-info" @click="status = 14,remark = requisition.remark" :disabled="spinner">Remark</button>
  </div>

  <div v-if="status" class="mb-2">
    <span
      class="badge rounded-pill"
      :class="{
        'bg-secondary': status == 2,
        'bg-danger': status == 4,
        'bg-success': status == 3,
        'bg-info': status != 3 && status != 4
      }"
      style="font-size: 1rem;"
    >
      {{
        status == 3
          ? 'Approve Request'
          : status == 4
          ? 'Reject Request'
            : status == 2
          ? 'Unapprove'
          : 'Fill Remark'
      }}
    </span>
  </div>

  <div class="input-group" v-if="status">
    <input
      type="text"
      class="form-control"
      :placeholder="status == 3 ? 'Enter Approval Remark' : status == 4 ? 'Enter Rejection Remark' : 'Enter Remark'"
      v-model="remark"
    >
    <button class="btn btn-primary" type="button" :disabled="spinner" @click="fillRequisitionRemark(requisition)">
      <span v-if="spinner" v-html="loadingSpinner()"></span>
      <span v-else>Save</span>
    </button>
  </div>

</div>

         <!-- approval button ends -->

        <form  @submit.prevent="registerIncidence()">
          <div class="row layout-top-spacing">
            
            <!-- Status & Incidence -->
            <div class="col-12  d-flex align-items-center justify-content-between">
     
              <div
              v-if="(requisition.status?.key === 'approved' || (requisition.status?.key === 'Partial Issued' )) && user_permissions.includes('can_create_issue_note')"
              class="d-flex align-items-center">
       
 

                <multiselect
                class="me-2"
                  v-model="store"
                  placeholder="Select Source Store"
                  label="name"
                  :options="stores"
                  style="width: 350px;"
                  :allow-empty="false"
                ></multiselect>
                
                <multiselect
                class="me-2"
                  v-model="purpose"
                  placeholder="Select Purpose"
                  :options="purposes"
                  style="width: 300px;"
                  :allow-empty="false"
                ></multiselect>
               

                 <multiselect
                class="me-2"
                  v-model="destination_store"
                  placeholder="Select Destination Store"
                  label="name"
                  :options="stores"
                  style="width: 350px;"
                  :allow-empty="false"
                  v-if="purpose == 'TRANSFER'|| purpose == 'CONVERSION'"
                ></multiselect>
                


                <button
                  v-if="store && purpose"
                  type="submit"
                  class="btn btn-primary btn-sm ms-2"
                 :disabled="spinner || (purpose !== 'CONSUMPTION' && !destination_store)"
                >
                  <div v-if="spinner" class="spinner-border text-white" role="status"></div>
                  <div v-else>Issue</div>
                </button>
              </div>

          
              
            </div>
                 <!-- <div v-if="approval_group_id == 6 && requisition?.status?.key === 'approved' && store " class="mt-2 col-xl-12 col-lg-12 col-sm-12 layout-spacing"> -->

                  <div v-if="approval_group_id == 6 " class="mt-2 col-xl-12 col-lg-12 col-sm-12 layout-spacing">

                  <div class="panel p-0">
                <div class="custom-table table3">
                  <table class="table table-bordered table-striped">
                    <thead>
                      <tr>
                        <th>Sno</th>
                        <th>Item Requested</th>
                        <th>Description</th>
                        <th>Quantity</th>
                        <th v-if="user_permissions.includes('can_create_issue_note') && (requisition.status?.key !== 'Issued' ) && store">Quantity Issuing</th>
                        <th v-if="user_permissions.includes('can_create_issue_note') && (requisition.status?.key !== 'Issued' ) && store ">Item Condition</th>
                      </tr>
                    </thead>
                    <tbody>
                      <tr v-for="(item,index) in requisitionItems" :key="item.id">
                        <td>{{ index + 1 }}</td>
                        <td>{{ item.item }}</td>
                        <td>{{ item.description }}</td>
                        <td v-if="user_permissions.includes('can_create_issue_note') && (requisition.status?.key !== 'Issued' ) && store">
                          <multiselect
                            v-model="item.store_item"
                            :options="storeItems"
                            placeholder="Select Item"
                            :searchable="true"
                            multple="false"
                            label="name"
                            :required="true"
                            :allow-empty="false"
                            @select="item.issued_quantity = ''"
                          ></multiselect>
                        </td>
                        <td>
                          <input 
                     v-if="user_permissions.includes('can_create_issue_note') && (requisition.status?.key !== 'Issued') && store && item.store_item"   
  type="number"
  class="form-control w-50"
  :placeholder="'available ' + item?.store_item?.balance_quantity ?? 0"
  v-model.number="item.issued_quantity"
  :max="Math.min(item.store_item.balance_quantity, item.quantity)"
  :min="0.1"
  @input="item.issued_quantity = Math.min(item.issued_quantity, item.store_item.balance_quantity, item.quantity - item.issued )"
 step="any"

  />
  <div v-if="requisition.status?.key !== 'Unapproved' && requisition.status?.key !== 'Issued'">
<span>Issued : {{ item.issued.toLocaleString() }}</span><br/>
<span>Pending : {{ (item.quantity - item.issued).toLocaleString() }}</span>

  </div>
  <div v-else>
    <span>{{ Number(item.quantity).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) }}</span>
  </div>

                        </td>

                         <td
                         v-if="user_permissions.includes('can_create_issue_note') && (requisition.status?.key !== 'Issued') && store"
                         >
                          <label
                            type="number"
                            class="form-control"
                          >{{item.store_item.condition ??'Select Item First'}}</label>
                        </td>

                      </tr>
                    </tbody>
                  </table>
                </div>
              </div>
            </div>
            <!-- Requisition Items -->
            <div v-if="!approval_group_id == 6 " :class="['col-lg-12', 'col-sm-12', 'layout-spacing', proforma || subcontractor ? 'col-xl-6' : 'col-xl-12']">
              <div class="panel p-0">
                <div class="custom-table table3">
                  <v-client-table :data="requisitionItems" :columns="itemColumns" :options="table_option"></v-client-table>
                </div>
              </div>

            </div>

            <!-- Issuing Items -->
  

            <!-- Proforma -->
       <div class="col-xl-6 col-lg-12 col-sm-12 layout-spacing" v-if="proforma">
  <div class="panel p-3 position-relative">
    <a :href="proforma" target="_blank" class="stretched-link"></a>
    <h4 class="text-center">Proforma Invoice</h4>
    <embed :src="proforma" type="application/pdf" width="100%" height="600px" />
  </div>
</div>

       <div class="col-xl-6 col-lg-12 col-sm-12 layout-spacing" v-if="subcontractor">
  <div class="panel p-3 position-relative">
    <a :href="subcontractor" target="_blank" class="stretched-link"></a>
    <h4 class="text-center">Subcontractor's Agreement</h4>
    <embed :src="subcontractor" type="application/pdf" width="100%" height="600px" />
  </div>
</div>

          </div>
        </form>

      </div>

      <!-- Footer -->
      <div class="modal-footer">
        <button type="button" class="btn btn-secondary" data-bs-dismiss="modal" @click="clearForm">Close</button>
      </div>
    </div>
  </div>
</div>


<!-- requisition items ends -->


    </div>
</template>

<script setup>
    import Multiselect from '@suadelabs/vue3-multiselect';
    import '@suadelabs/vue3-multiselect/dist/vue3-multiselect.css';
    import { onMounted, ref,inject,computed,watch } from 'vue';
    import axios from 'axios';
    import { useMeta } from '@/composables/use-meta';
    import '@/assets/sass/scrollspyNav.scss';
    import { globalSearch } from '@/components/reusables/globalSearch';

    useMeta({ title: 'Requisition Group' });

    const axiosInstance = axios.create({
        baseURL: process.env.VUE_APP_API_BASE_URL
    });

    import { useRouter, useRoute } from 'vue-router';
    const showTrash = ref(false);
    const router = useRouter();
    const route = useRoute(); // Import useRoute from vue-router
     const user_permissions = JSON.parse(localStorage.getItem("user")).permissions;
    const requisitionTypes = ref([]);
    const requisition_type = ref('');
    const spinner = ref(false)
    const incidence = ref('')
    const tableShimmer = inject('tableShimmer');
    const formatNumber = inject('formatNumber');
    const loadingSpinner = inject('loadingSpinner');
    const status = ref('')
    const item = ref('')
    const quantity = ref('')
    const rate = ref('')
    const remark = ref()
    const units = ref('')
    const remarks = ref([])
    const item_id = ref(0)
    const requisitions = ref([]);
    const loading_spinner = ref(false);
    const columns = ref(['sno','ref_no', 'requester','purpose','type','project','date','cost','status','remark',  'actions']);
    const role_registration = ref(false);
    const showMessage = inject('showMessage');
    const showError = inject('showError');
    const destination_store = ref('')
    const unitList = ref([])

       const filter = ref('')


const filteredRequisitions = computed(() => {
  if(user_permissions.includes('is_md')){
if (showTrash.value) {
    return globalSearch(requisitions.value, filter.value).filter(r =>
      ['Rejected', 'On Hold', 'Remarked'].includes(r.status?.key)
    );
  } else {
    return globalSearch(requisitions.value, filter.value).filter(r =>
      ['Unapproved', 'approved','Issued','Partial Issued'].includes(r.status?.key)
    );
  }
  }else{
   return globalSearch(requisitions.value, filter.value);
  }
  
});




const assets= ref([])
const getAssets = async ()=>{
  const response = await axiosInstance.get('machines')
  assets.value = response.data.map((item)=>({
  ...item,
  name : item.name + ' - ' + item.type_name
  }))
}

const projects = ref([])
const project = ref('')

const getProjects = async ()=>{
  const response = await axiosInstance.get('projects')
  projects.value = response.data
}

const budgets = ref([])
const budget = ref('')
const getBudgets = async (id) => {
  const response = await axiosInstance.get(`budgets?project_id=${id}`)
  budgets.value = response.data.filter(b => b.status === 'closed')
}


watch(project, (newVal) => {
    if (newVal) {
        getBudgets(newVal.id)
    }
});




const budgetItems = ref([])
const budget_item = ref('')
watch(budget, (newVal) => {
    if (newVal) {
         budgetItems.value = newVal.items
    }
});

const budgetItemDescriptions = ref([])
const budget_item_description = ref('')
const max_cost = ref('')
const max_quantity = ref('')
watch(budget_item, (newVal) => {
    if (newVal) {
         budgetItemDescriptions.value = newVal.descriptions
         item.value = newVal.name
    }
});

watch(budget_item_description, (newVal) => {
    if (newVal) {
         max_quantity.value = newVal.quantity * newVal.quantity_2,
         max_cost.value = (newVal.quantity * newVal.quantity_2 * newVal.cost) - newVal.used_cost
         item_id.value = newVal.id
         description.value = newVal.name
         units.value = newVal.units
    }
});



watch(() => route.params.status_id, (newStatusId) => {
  loading_spinner.value = true;
  getRequisitions();
});


const getUnits = async ()=>{
  const response = await axiosInstance.get('units')
  unitList.value = response.data
}

const fillRequisitionRemark = async (requisition) => {
  spinner.value = true
  const payload = {
    status_id: status.value,
    remark: remark.value,
    ...(status.value == 3 && approval_group_id != 6 && {
      approval: {
        approval_group_id: requisition.approval_group_id,
        source: 'requisition',
        source_id: requisition.id,
        requester_id: JSON.parse(localStorage.getItem("user")).id,
        items: requisition.items
      }
    })
  }

//   console.log(payload)
//   return ;
  try{
    const response = await axiosInstance.put(`requisitions/${requisition.id}`,payload)
     getRequisitions();
    showMessage("Saved Successfully")
    document.getElementById('close-issue-modal').click()
  }catch(error){
    console.log(error)
    showError(error.message)
  }finally{
    spinner.value = false
  }
}

    const purpose = ref('')
    const purposes = ref(['TRANSFER','CONSUMPTION','CONVERSION'])
    const registerIncidence = async () => {
      spinner.value = true;
      const payload = {
        issueData: {
          requisition_id: requisition.value.id,
          issuer_id: JSON.parse(localStorage.getItem("user")).id,
          destination_store_id: destination_store.value.id,
          source_store_id : store.value.id,
          remark :  destination_store.value.id == 0 ? 'DIRECT CONSUMPTION' : 'SENT TO ' + destination_store.value.name ,
          status_id : purpose.value == 'CONSUMPTION' ? 15 : purpose.value == 'CONVERSION' ? 28 : 9 ,
          purpose: purpose.value
        },
        issueItems: requisitionItems.value
          .filter(item => Number(item.issued_quantity) > 0)
          .map(item => ({
            requisition_item_id: item.id,
            store_item_id: item.store_item.id,
            quantity: item.issued_quantity
          }))
      };
      
      try {
        const response = await axiosInstance.post('good-issue-notes', payload);
        showMessage('Issued to ' + destination_store.value.name);
        getRequisitions();
        document.getElementById('close-issue-modal').click();
        purpose.value = '';
      } catch (error) {
        showError(error.message);
        console.log(error);
      } finally {
        spinner.value = false;
      }
    }
    
    watch(purpose, (newVal) => {
    if (newVal) {
        destination_store.value = ''
    }
});

    
    const table_option = ref({
        perPage: 50,
        perPageValues: [  50 ,100 ,200 ,500 ],
        skin: 'table table-hover table-striped',
        columnsClasses: { actions: 'actions text-center' },
        sortable: ['id', 'role_name'],
        sortIcon: {
            base: 'sort-icon-none',
            up: 'sort-icon-asc',
            down: 'sort-icon-desc',
        },
        pagination: { nav: 'scroll', chunk: 5 },
        texts: {
            count: 'Showing {from} to {to} of {count}',
            filter: '',
            filterPlaceholder: 'Search...',
            limit: 'Results:',
        },
        resizableColumns: false,
    });


const items_list = ref([])
    const getItems = async (source) => {
        const response = await  axiosInstance.get(source)
        items_list.value = response.data.map((item, index) => ({
            ...item,
            SNo: index + 1,
            name : item.name + (item.description ? ' - ' + item.description : ''),
            unit:item.unit ?? '---'
        }));
    };

    const labours = ref([])
    const getLabours = async () => {
        const response = await axiosInstance.get('/labour-types')
        labours.value = response.data
    };


watch(requisition_type, (newVal) => {
    if (newVal === 'spares') getItems('get-spares');
    if (newVal === 'labour') getLabours();
    if (newVal === 'construction materials') getItems('get-materials');
});

watch(item, (newVal) => {
