const description = ref('')



    const requisitionItems = ref([])
 const itemColumns = ref(['Sno','item','description','units', 'quantity','rate','total']);


    const clearForm = () =>{
      requisitionItems.value= ([])
      incidence.value = '',
      remark.value = '',
      status.value = ''
      budget.value = ''
      budget_item.value = ''
      project.value = ''
      units.value = ''
      item.value = ''
      quantity.value = ''
      rate.value = ''
      description.value = ''
      requisition_type.value = ''
      budget_item_description.value = ''
      budgets.value = []
      budgetItems.value = []
      budgetItemDescriptions.value = []
      store.value = ''
      destination_store.value = ''
      purpose.value = ''
    }


    const proforma = ref('')
    const subcontractor = ref('')
    const requisition = ref('')
    const fillItems = (req) => {
    requisition.value = req
    remarks.value = req.remarks
    proforma.value = req.attachment
    subcontractor.value = req.subcontractor?.attachment 
    ? 'https://copex.trustdigital.space/' + req.subcontractor.attachment 
    : null

    requisitionItems.value = req.items.map((item, index) => ({
        ...item,
        Sno: index + 1,
        item: item.remark,
        description :item.description,
        // rate: Number(item.rate).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + '/=',
        rate: Number(item.rate).toLocaleString()+'/=',
        total : (item.quantity * item.rate).toLocaleString()+'/=',
        issued_quantity : '',
        store_item: ''
    }));

    }



  const status_id = route.params.status_id; 
  const approval_group_id = route.params.approval_group_id; 
  
  const getRequisitions = () => {
  let url = "requisitions";
  if (status_id && status_id !== "all") {
    url += `?status_id=${status_id}&approval_group_id=${approval_group_id}`;
  }else{
     url += `?approval_group_id=${approval_group_id}`;
  }
  
  axiosInstance.get(url)
    .then((response) => {
      requisitions.value = response.data.map((item, index) => {
        const type = requisitionTypes.value.find(t => t.id === item.requisition_type_id);
        return {
          ...item,
          ref_no : item.id,
          Sno: index + 1,
          requester_email: item.requester_email,
          type: item.type,
          purpose : item.approval_group,
          attachment: item.attachment ? 'https://bushman.ink/' + item.attachment : null,
          status_id: item.status.id,
          cost: formatNumber(item.items.reduce((total, it) => total + it.quantity * it.rate, 0)),
            status: (() => {
            // Calculate total quantity of all items
            const totalQuantity = item.items.reduce((sum, it) => sum + Number(it.quantity), 0);
            // If status is 'Issued' and issued_items < total quantity, set to 'Partial Issued'
            if (item.status === 'Issued' && Number(item.issued_items) < totalQuantity) {
              return {
              key: 'Partial Issued',
              class: 'warning'
              };
            }
            return {
              key: item.status,
              class: item.status_color
            };
            })(),
        };
      });
      loading_spinner.value = false;
    })
    .catch((error) => {
      showError(error.message);
      loading_spinner.value = false;
    });
};

    
    
    const storeItems = ref([])
    const getStoreItems = async (id) =>{
      const response = await axiosInstance.get(`get-store-items?store_id=${id}`)
      storeItems.value  = response.data
    }

       const stores = ref('')
       const store = ref('')
        const getStores = async () =>{
      const response = await axiosInstance.get('stores')
      stores.value  = [
        ...response.data.map((item)=>({
        ...item,
        name : item.project + ' - ' + item.name
      }))
    ]
    }

    watch(store, (newVal) => {
      storeItems.value = ['']
        getStoreItems(newVal.id)
});

const enforceMax = () => {
  if(requisition_type.value ==='budget'){
      if (quantity.value > max_quantity.value ) {
        quantity.value = max_quantity.value
        showError("only "+ quantity.value + " available")
      }

       if ((quantity.value * rate.value) > max_cost.value ) {
        rate.value = ''
        showError("Cost should not exceed "+ formatNumber(max_cost.value) )
      }
  }

    }

   
    onMounted(async () => {
